SELECT id, isbn, title, author, description, total_copies, available_copies, version
FROM book
WHERE id = #{id}

SELECT id, isbn, title, author, description, total_copies, available_copies, version FROM book
WHERE title LIKE CONCAT('%', #{keyword}, '%') OR author LIKE CONCAT('%', #{keyword}, '%')
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}
